import ClearSearchIcon from '../../../assets/icons/close.svg';
import SearchIcon from '../../../assets/icons/input-search.svg';
import {
  InputSearchClearIcon,
  InputSearchContainer,
  InputSearchIcon,
  InputSearchInput,
} from './InputSearch.styles';

interface InputSearchProps {
  value?: string;
  onChange: (value: string) => void;
}

export const InputSearch = ({ value = '', onChange }: InputSearchProps) => {
  const handleClearSearch = () => {
    onChange('');
  };

  return (
    <InputSearchContainer>
      <InputSearchIcon src={SearchIcon} alt="Search Icon" />
      <InputSearchInput
        value={value}
        placeholder="Search for training materials"
        onChange={(e) => onChange(e.target.value)}
      />
      <InputSearchClearIcon
        visible={value !== ''}
        src={ClearSearchIcon}
        alt="Clear Search Icon"
        onClick={handleClearSearch}
      />
    </InputSearchContainer>
  );
};
